import{_ as e,o as a,c as r,a0 as s}from"./chunks/framework.BTg7EidG.js";const g=JSON.parse('{"title":"Skills & Research","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skills.md","filePath":"guide/skills.md"}'),d={name:"guide/skills.md"};function h(i,t,n,o,l,c){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="skills-research" tabindex="-1">Skills &amp; Research <a class="header-anchor" href="#skills-research" aria-label="Permalink to &quot;Skills &amp; Research&quot;">​</a></h1><h2 id="where-each-art-is-taught" tabindex="-1">Where each art is taught <a class="header-anchor" href="#where-each-art-is-taught" aria-label="Permalink to &quot;Where each art is taught&quot;">​</a></h2><p>The <strong>Town Hall</strong> teaches one art per class per tier — the old three. Everything else is taught where the trade actually lives, which is a reason to raise those structures beyond drilling in them:</p><table tabindex="0"><thead><tr><th>Building</th><th>What it teaches</th></tr></thead><tbody><tr><td><strong>Barracks</strong></td><td>Blinding Dust, Bulwark</td></tr><tr><td><strong>Laboratory</strong></td><td>Quickening Balm, Vitriol Flask, Quicken</td></tr><tr><td><strong>Shadow Guild</strong></td><td>Shadow Step, Assassinate, Poison Blade</td></tr><tr><td><strong>Bestiary</strong></td><td>Beast Bond, Wild Heart, Ensnare</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Nothing is innate</p><p>Your Lord begins with steel and a title, not a technique. <strong>Every</strong> skill is studied at a Town Hall — including your own class&#39;s art, which is simply the cheapest project on the list and the one to start with.</p></div><p>Every hero carries up to <strong>three skills</strong>, and every one of them is studied first and assigned afterward from the unit sheet — including the art of their own class.</p><h2 id="used-or-simply-carried" tabindex="-1">Used, or simply carried <a class="header-anchor" href="#used-or-simply-carried" aria-label="Permalink to &quot;Used, or simply carried&quot;">​</a></h2><p>Skills come in two kinds, and the unit sheet marks which is which:</p><ul><li><strong>Passive</strong> arts apply themselves. Rally, Shield Wall, Plunder, Field Mending and the rest are simply true while the hero lives.</li><li><strong>Active</strong> arts are <em>used</em> on the battlefield and spend the hero&#39;s action for that turn — Transmute Blast, Quickening Balm, Vitriol Flask, Shadow Step, Assassinate, Ensnare, Blinding Dust and Quicken. They appear as buttons in the tactical dock when it is that hero&#39;s go.</li></ul><h2 id="how-research-works" tabindex="-1">How research works <a class="header-anchor" href="#how-research-works" aria-label="Permalink to &quot;How research works&quot;">​</a></h2><p>Research happens at the <strong>Town Hall</strong> of any city you own; the hall&#39;s level is the city&#39;s level, and it gates what can be studied:</p><table tabindex="0"><thead><tr><th>Hall level</th><th>Opens</th><th>Cost</th><th>Time</th></tr></thead><tbody><tr><td>1</td><td>The class arts (tier 1)</td><td>60🪙 4💎</td><td>2 days</td></tr><tr><td>2</td><td>The deeper studies (tier 2)</td><td>150🪙 10💎</td><td>5 days</td></tr><tr><td>3</td><td>The masterworks (tier 3)</td><td>200🪙 16💎</td><td>6 days</td></tr></tbody></table><p>One project sits on the bench at a time, guild-wide. Once a skill is mastered it belongs to the whole guild forever: <strong>any hero of the right class</strong> can assign it from their unit sheet, from that day on, and a mastered skill can be unassigned and reassigned freely.</p><h2 id="the-warrior-s-line" tabindex="-1">The warrior&#39;s line <a class="header-anchor" href="#the-warrior-s-line" aria-label="Permalink to &quot;The warrior&#39;s line&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>What it does</th></tr></thead><tbody><tr><td>📣 Rally</td><td>1</td><td>The whole party fights at +2 attack and +2 defense while this hero leads</td></tr><tr><td>🛡 Shield Wall</td><td>2</td><td>The party braces at +3 defense whenever it is the one attacked</td></tr><tr><td>📯 Warcry</td><td>3</td><td>The enemy line falters: every foe fights at −2 defense</td></tr></tbody></table><p>Warriors anchor a line. Rally is always on; Shield Wall turns a garrisoned warrior hero into a wall worth breaking armies on; Warcry is the siege-breaker, softening a deep garrison before the blades cross. Rally and Warcry together swing every exchange by four points.</p><h2 id="the-rogue-s-line" tabindex="-1">The rogue&#39;s line <a class="header-anchor" href="#the-rogue-s-line" aria-label="Permalink to &quot;The rogue&#39;s line&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>What it does</th></tr></thead><tbody><tr><td>🌫 Ambush</td><td>1</td><td>A free opening volley whenever this party attacks, +15% to a fleeing Lord&#39;s escape, and ambushes are sprung more often</td></tr><tr><td>🪙 Plunder</td><td>2</td><td>Hoards turn up in 60% of taken holds instead of 40%, and dungeon chests run half again as rich</td></tr><tr><td>⚔ Overwhelm</td><td>3</td><td>The class counter (warrior beats rogue beats alchemist beats warrior) deals double damage instead of half again, for the whole party</td></tr></tbody></table><p>Rogues profit from initiative and greed. Ambush makes every attack begin a step ahead; Plunder pays for itself within a few raids, and it belongs on whichever hero storms the most holds; Overwhelm rewards building a party that counters what your enemy fields. Rogue heroes also sneak parties past dungeon floors, and flee down stairs mid-fight.</p><h2 id="the-alchemist-s-line" tabindex="-1">The alchemist&#39;s line <a class="header-anchor" href="#the-alchemist-s-line" aria-label="Permalink to &quot;The alchemist&#39;s line&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>What it does</th></tr></thead><tbody><tr><td>⚗️ Transmute Blast</td><td>1</td><td>Opens battle by burning half the hero&#39;s Essence as damage that ignores armor (on the tactical field, a cast at range 3)</td></tr><tr><td>🩹 Field Mending</td><td>2</td><td>The whole party heals an extra 10% of max HP every day, even on the march</td></tr><tr><td>🌀 Quicksilver March</td><td>3</td><td>The hero&#39;s craft lightens every boot: the party marches +3 move points a day</td></tr></tbody></table><p>Alchemists win wars between the battles. Transmute Blast scales with Essence, so a leveled alchemist Lord opens with a thunderclap; Field Mending keeps a campaigning army whole without ever going home; and Quicksilver March makes one army fight like two by arriving first. Put March on the party that answers threats, and Mending on the one that never stops pushing.</p><h2 id="the-arts-taught-in-the-trade-halls" tabindex="-1">The arts taught in the trade halls <a class="header-anchor" href="#the-arts-taught-in-the-trade-halls" aria-label="Permalink to &quot;The arts taught in the trade halls&quot;">​</a></h2><p>These are not on the Town Hall&#39;s bench. Each is studied where its trade lives, which is the reason to raise those buildings past drilling in them. Most are <strong>active</strong> — used on the battlefield, spending the hero&#39;s turn.</p><h3 id="barracks-·-the-warrior-s-yard" tabindex="-1">Barracks · the warrior&#39;s yard <a class="header-anchor" href="#barracks-·-the-warrior-s-yard" aria-label="Permalink to &quot;Barracks · the warrior&#39;s yard&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>Used?</th><th>What it does</th></tr></thead><tbody><tr><td>💨 Blinding Dust</td><td>2</td><td>active</td><td>Grit in a foe&#39;s eyes: their blows go wide half the time for two turns</td></tr><tr><td>🧱 Bulwark</td><td>3</td><td>passive</td><td>A hero who spends their turn holding ground gives +2 guard to every ally beside them</td></tr></tbody></table><h3 id="laboratory-·-the-alchemist-s-bench" tabindex="-1">Laboratory · the alchemist&#39;s bench <a class="header-anchor" href="#laboratory-·-the-alchemist-s-bench" aria-label="Permalink to &quot;Laboratory · the alchemist&#39;s bench&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>Used?</th><th>What it does</th></tr></thead><tbody><tr><td>💧 Quickening Balm</td><td>2</td><td>active</td><td>Lays a balm over a patch of ground that settles a few battlefield turns later and heals every ally standing in it</td></tr><tr><td>⏱ Quicken</td><td>2</td><td>active</td><td>Hurries one ally: they come round in the turn order much sooner</td></tr><tr><td>🧪 Vitriol Flask</td><td>3</td><td>active</td><td>Hurls a flask that eats everything in a three-tile square — friend and foe alike, so mind the throw</td></tr></tbody></table><p>Quickening Balm is shared: learning it opens it for <strong>Beastmasters</strong> too, though in their hands it tends only the beasts.</p><h3 id="shadow-guild-·-the-rogue-s-trade" tabindex="-1">Shadow Guild · the rogue&#39;s trade <a class="header-anchor" href="#shadow-guild-·-the-rogue-s-trade" aria-label="Permalink to &quot;Shadow Guild · the rogue&#39;s trade&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>Used?</th><th>What it does</th></tr></thead><tbody><tr><td>🌑 Shadow Step</td><td>2</td><td>active</td><td>Melts into cover: much harder to hit until this hero&#39;s next turn</td></tr><tr><td>🗡 Assassinate</td><td>3</td><td>active</td><td>A killing blow struck from behind a foe — or from above. Nothing from the front</td></tr><tr><td>🧪 Poison Blade</td><td>3</td><td>passive</td><td>This hero&#39;s blows leave a wound that keeps bleeding for three battlefield turns</td></tr></tbody></table><h3 id="bestiary-·-the-keeper-s-arts" tabindex="-1">Bestiary · the keeper&#39;s arts <a class="header-anchor" href="#bestiary-·-the-keeper-s-arts" aria-label="Permalink to &quot;Bestiary · the keeper&#39;s arts&quot;">​</a></h3><p>Only a <strong>Beastmaster raised to hero</strong> can carry these — never an ordinary rogue.</p><table tabindex="0"><thead><tr><th>Skill</th><th>Tier</th><th>Used?</th><th>What it does</th></tr></thead><tbody><tr><td>🕸 Ensnare</td><td>2</td><td>active</td><td>Throws a net over one foe: they cannot take a step for two turns, though they can still fight</td></tr><tr><td>🐾 Beast Bond</td><td>2</td><td>passive</td><td>Every beast in this hero&#39;s party fights at +3 attack and +3 defense</td></tr><tr><td>🫀 Wild Heart</td><td>3</td><td>passive</td><td>Beasts in this party keep for half the gold, and mend 15% of their health each day</td></tr></tbody></table><h2 id="reading-the-research-screen" tabindex="-1">Reading the research screen <a class="header-anchor" href="#reading-the-research-screen" aria-label="Permalink to &quot;Reading the research screen&quot;">​</a></h2><p>Open any city&#39;s <strong>Research</strong> tab: each skill shows its class, tier, cost, and state. <em>Available</em> means it can go on the bench today; <em>researching</em> is the current project; <em>mastered</em> means done and assignable by any hero of that class. A skill grayed with &quot;needs hall 2/3&quot; wants the city upgraded first, and upgrading any one city to level 3 opens the masterworks for the whole guild.</p>',36)])])}const b=e(d,[["render",h]]);export{g as __pageData,b as default};
